#!/bin/sh
cd "$(dirname "$0")"
node -e 'const fs=require("fs"),r=f=>fs.readFileSync(f,"utf8");let h=r("src/app.html").replace("/*STATS*/",()=>r("src/stats.js").replace(/if \(typeof module[^\n]*\n?$/,"")+"\n"+r("src/sem.js")+"\n"+r("src/glm2.js")).replace("/*DB*/",()=>r("src/sav.js")+"\n"+r("src/xlsx.js")+"\n"+r("src/db.js")+"\n"+r("src/semui.js")+"\n"+r("src/parcel.js")+"\n"+r("src/reg2.js")+"\n"+r("src/medmod.js")+"\n"+r("src/modmed.js")+"\n"+r("src/serial.js")+"\n"+r("src/lmguide.js")+"\n"+r("src/cluster.js")+"\n"+r("src/codebook.js")+"\n"+r("src/pick.js")+"\n"+r("src/rlink.js")+"\n"+r("src/prep.js")+"\n"+r("src/power.js")+"\n"+r("src/nav.js")+"\n"+r("src/agree.js")+"\n"+r("src/rcode.js")+"\n"+r("src/corr.js")+"\n"+r("src/export.js")+"\n"+r("src/record.js"));fs.writeFileSync("index.html","<!doctype html>\n<html lang=\"ja\">\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n"+h)'
SP="$1"; [ -n "$SP" ] && (printf '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body>\n'; cat index.html; printf '</body></html>') > "$SP/prev/index.html"
